mapper.delete:
DELETE FROM sys_role_menu
WHERE tenant_id = #{tenantId}
  AND role_id = #{roleId}

mapper.select:
SELECT menu_id FROM sys_role_menu
WHERE tenant_id = #{tenantId} AND role_id = #{roleId}
ORDER BY menu_id

SELECT DISTINCT m.permission_code FROM sys_role_menu rm INNER JOIN sys_role r ON r.id = rm.role_id AND r.tenant_id = rm.tenant_id INNER JOIN sys_menu m ON m.id = rm.menu_id WHERE rm.tenant_id = #{tenantId} AND r.tenant_id = #{tenantId} AND r.status = 'ENABLED' AND r.deleted = 0 AND m.status = 'ENABLED' AND m.deleted = 0 AND m.type = 'BUTTON' AND m.permission_code IS NOT NULL AND rm.role_id IN
#{roleId}
ORDER BY m.permission_code
